arguments.command:
pkill -f fuzz2.py; cd /workspace && python3 - <<'EOF'
p='/workspace/tmp/brute.py'
s=open(p).read()
old = """    best=None
    for combo in itertools.product(*per):
        if sum(c[2] for c in combo)>budget: continue
        w=sum(c[0] for c in combo); p=sum(c[1] for c in combo)
        if best is None or (w,p)<best: best=(w,p)
    return best"""
new = """    # per version: best (work, pages) for each exact number of resident pages
    tables=[]
    for opts in per:
        table={}
        for (w,p,u) in opts:
            cur=table.get(u)
            if cur is None or (w,p)<cur: table[u]=(w,p)
        tables.append(table)
    # knapsack over the shared resident budget
    states={0:(0,0)}
    for table in tables:
        new={}
        for used,(w,p) in states.items():
            for u,(vw,vp) in table.items():
                if used+u>budget: continue
                cand=(w+vw,p+vp)
                cur=new.get(used+u)
                if cur is None or cand<cur: new[used+u]=cand
        states=new
    best=None
    for used,(w,p) in states.items():
        if best is None or (w,p)<best: best=(w,p)
    return best"""
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
print('patched')
EOF
cd /workspace && timeout 170 python3 /tmp/fuzz2.py 1 40
